private loadTestCasesFromExcel(filePath: string): { testCases: TestCaseDefinition[]; rawRows: any[] } {
  const workbook = XLSX.readFile(filePath);
  const sheet = workbook.Sheets[workbook.SheetNames[0]]; // first sheet only
  // defval: '' emits blank cells as '' instead of omitting the key, so row['Action'] etc. are always safe to .trim().
  const rows: any[] = XLSX.utils.sheet_to_json(sheet, { defval: '' });

  // Group one-row-per-step into one-test-case-per-Title; Map preserves sheet order -> steps stay sequential.
  const testCaseMap = new Map<string, TestCaseDefinition>();
  for (const row of rows) {
    const title = row['Title'];
    if (!title) continue; // skip spacer/blank-title rows so they don't create phantom cases

    // First row for a title seeds the case; Priority/Story ID repeat down the step rows, so capture once.
    if (!testCaseMap.has(title)) {
      testCaseMap.set(title, {
        title,
        priority: row['Priority'] || 'P2', // default priority when the cell is blank
        storyId: String(row['Story ID'] || ''),
        steps: [],
      } as any);
    }
    testCaseMap.get(title)!.steps.push({
      stepNum: parseInt(row['Step #'] || '1', 10),
      action: String(row['Action'] || '').trim(),
      // A blank expected result is meaningless in ADO, so substitute a generic assertion.
      expectedResult: String(row['Expected Result'] || '').trim() || 'Verify action completes successfully',
    });
  }
  return { testCases: [...testCaseMap.values()], rawRows: rows };
}

private async createTestCase(tc: TestCaseDefinition, assignedTo?: string): Promise<{ id: number; url: string } | null> {
  const stepsXml = this.stepsToXml(tc.steps);

  // A work item is created via a JSON-Patch doc: one 'add' op per field, keyed by ADO REFERENCE NAME (not the UI label).
  const patches: JsonPatchOperation[] = [
    { op: 'add', path: '/fields/System.Title', value: tc.title },
    { op: 'add', path: '/fields/Microsoft.VSTS.TCM.Steps', value: stepsXml }, // steps live in ONE field as serialized XML
    { op: 'add', path: '/fields/Microsoft.VSTS.Common.Priority', value: this.parsePriority(tc.priority) }, // 'P2' -> numeric 1-4
  ];
  // Conditional: a case with no owner is still valid, so only add AssignedTo when we have one.
  if (assignedTo) patches.push({ op: 'add', path: '/fields/System.AssignedTo', value: assignedTo });

  if (tc.storyId) {
    patches.push({
      op: 'add',
      path: '/relations/-', // '-' appends to the relations array
      value: {
        // TestedBy-REVERSE: from the test case's side this reads 'this case tests that story'; Forward would link it backwards.
        rel: 'Microsoft.VSTS.Common.TestedBy-Reverse',
        url: `https://dev.azure.com/my-org/_apis/wit/workItems/${tc.storyId}`, // must be a full REST work-item URL, not a bare ID
        attributes: { comment: `Tests US ${tc.storyId}` },
      },
    });
  }
  const result = await this.client.createWorkItem('Test Case', patches);
  return { id: result.id, url: result._links?.html?.href };
}

private stepsToXml(steps: TestStep[]): string {
  // steps header: last=N is the step count ADO uses to number the rendered list.
  let xml = '<steps id="0" last="' + steps.length + '">';
  for (const step of steps) {
    // Escape the user's text first - a raw < or & in an action would corrupt the surrounding XML.
    const action = this.escapeXml(step.action);
    const expected = this.escapeXml(step.expectedResult);
    // ValidateStep (not plain action) is what gives the step a verifiable expected-result column.
    xml += `<step id="${step.stepNum}" type="ValidateStep">`;
    // TWO parameterizedStrings per step, in order: [0] action, [1] expected result.
    // Double-encoded: the value is HTML (<DIV><P>) but lives inside XML, so its brackets are entity-escaped (&lt;/&gt;).
    xml += `<parameterizedString isformatted="true">&lt;DIV&gt;&lt;P&gt;${action}&lt;/P&gt;&lt;/DIV&gt;</parameterizedString>`;
    xml += `<parameterizedString isformatted="true">&lt;DIV&gt;&lt;P&gt;${expected}&lt;/P&gt;&lt;/DIV&gt;</parameterizedString>`;
    xml += `<description/></step>`;
  }
  xml += '</steps>';
  return xml;
}

private createStepsMappingWithIds(results: TestCaseResult[], outputDir: string): string {
  const rows: StepMapping[] = [];
  // Un-group back to one-row-per-step (inverse of the load step) so every input row reappears...
  for (const result of results) {
    for (const step of result.testCase.steps) {
      rows.push({
        title: result.testCase.title,
        stepNum: step.stepNum,
        action: step.action,
        expectedResult: step.expectedResult,
        // ...now stamped with what it became. || undefined -> a FAILED creation leaves a blank cell, not a misleading 0/null.
        adoId: result.adoId || undefined,
        adoUrl: result.url || undefined,
      });
    }
  }
  const worksheet = XLSX.utils.json_to_sheet(rows);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'Steps With IDs');
  // Timestamp in the filename so each import keeps its own dated receipt instead of overwriting the last.
  const filePath = path.join(outputDir, `ADO_Steps_Mapping_WithIDs_${this.getTimestamp()}.xlsx`);
  XLSX.writeFile(workbook, filePath);
  return filePath;
}

